const audioKey = (path) => `./${path}?v=${AUDIO[path]}`;

async function cacheAudio(paths, concurrency = 6) {
  const cache = await caches.open(AUDIO_CACHE);
  const have = new Set((await cache.keys()).map((r) => r.url));
  const todo = paths.filter((p) => !have.has(new URL(audioKey(p), self.location).href));
  let i = 0;
  const worker = async () => {
    while (i < todo.length) {
      const p = todo[i++];
      try {
        const res = await fetch(`./${p}`, { cache: 'no-cache' });
        if (res.ok) await cache.put(audioKey(p), res);
      } catch {
        /* offline or interrupted: tried again next time */
      }
    }
  };
  await Promise.all(Array.from({ length: concurrency }, worker));
}

async function pruneAudio() {
  const cache = await caches.open(AUDIO_CACHE);
  const keep = new Set(Object.keys(AUDIO).map((p) => new URL(audioKey(p), self.location).href));
  for (const req of await cache.keys()) if (!keep.has(req.url)) await cache.delete(req);
}

let warming = null;
function warmAudio() {
  // Core recordings first (spelling words, instructions, story), then everything else.
  if (!warming) warming = cacheAudio(AUDIO_CORE, 4).then(() => cacheAudio(Object.keys(AUDIO), 3)).finally(() => (warming = null));
  return warming;
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('writequest-') && k !== CACHE && k !== AUDIO_CACHE).map((k) => caches.delete(k))))
      .then(() => pruneAudio())
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // Recorded audio: from the audio cache, by content hash.
  const scope = new URL('./', self.location).pathname;
  const rel = url.pathname.startsWith(scope) ? url.pathname.slice(scope.length) : '';
  if (rel.startsWith('audio/') && AUDIO[decodeURIComponent(rel)]) {
    const path = decodeURIComponent(rel);
    event.respondWith(
      caches.open(AUDIO_CACHE).then((cache) =>
        cache.match(audioKey(path), { ignoreVary: true }).then(
          (hit) =>
            hit ||
            fetch(req).then((res) => {
              if (res.ok) cache.put(audioKey(path), res.clone());
              return res;
            }),
        ),
      ),
    );
    return;
  }

  // App shell: network first (fresh when online), cached shell when offline.
  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req)
        .then((res) => {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put('./', copy));
          return res;
        })
        .catch(() => caches.match('./').then((r) => r || caches.match('./index.html'))),
    );
    return;
  }

  // Hashed assets: cache first. Module scripts loaded later (lazy screens) are
  // requested with an Origin header; ignore Vary so the precached copy matches.
  event.respondWith(
    caches.match(req, { ignoreVary: true }).then(
      (hit) =>
        hit ||
        fetch(req).then((res) => {
          if (res.ok) {
            const copy = res.clone();
            caches.open(CACHE).then((c) => c.put(req, copy));
          }
          return res;
        }),
    ),
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
  // The page asks for the rest of the audio once it has loaded (and the device is not saving data).
  if (event.data === 'warm-audio') event.waitUntil(warmAudio());
  if (event.data === 'audio-status')
    event.waitUntil(
      caches
        .open(AUDIO_CACHE)
        .then((c) => c.keys())
        .then((keys) => event.source && event.source.postMessage({ type: 'audio-status', cached: keys.length, total: Object.keys(AUDIO).length })),
    );
});
